%% ESM / SPES-CCEP Practice Survey: manuscript numbers
% Computes the numbers reported in the manuscript (counts and percentages,
% Table 1, and the association analyses) and prints them in manuscript order,
% labeled by results section. Figures are generated by ESM-SPES-CCEP-figures.m.
%
% Input : survey export (.xlsx), sheet 'Form Responses 1' (see Configuration)
% Output: written to one results folder (resultsDir), shared with the figure script:
%   manuscript_numbers_report.txt     full console report (diary)
%   numbers_long.csv                  every tabulated count: section,
%                                     variable, category, n, denominator, %
%   stats_region_KW.csv               permutation Kruskal-Wallis by Region
%   stats_agegroup_KW.csv             permutation Kruskal-Wallis by Age Group
%   stats_ieegvolume_spearman.csv     permutation Spearman, iEEG volume vs ESM
%
% Statistical approach:
%   - Ordinal outcomes vs Region / Age Group: permutation Kruskal-Wallis
%     (tie-corrected H, group labels permuted, add-one p-value).
%   - Annual iEEG volume vs ESM outcomes: permutation Spearman, two-sided.
%   - Benjamini-Hochberg FDR within each family: Region (12 tests), Age Group
%     (12 tests), iEEG volume (9 tests). The ESM-only 9-test FDR column is
%     printed as an additional sensitivity.
%   - Multi-select questions, SPES/CCEP and Academic vs Private: descriptive only.
%
% Implementation notes:
%   - The random number generator is seeded (rngSeed), so permutation p-values
%     are reproducible.
%   - The PctESM label "0% (can skip this section)" is cleaned to "0%" so that
%     centers that do not use ESM are included (cleanPctESMLabel).
%   - Permutation p-values compare statistics with a small tolerance
%     (1e-9 / 1e-12) to avoid floating-point tie misses.
%   - Tie-ranks, Spearman correlation and BH-FDR are implemented locally; no
%     toolbox is required.
%
% Requirements: MATLAB R2019b or later (readcell).

clear; clc; close all;

%% ============================================================
% 0. CONFIGURATION
% =============================================================
% Paths are relative to this script. Expected layout:
%   <repo>/ESM-SPES-CCEP-stats.m  (this script)
%   <repo>/data/                   survey export (not included in the repository)
%   <repo>/results/                created automatically; all outputs are written here
dataFile   = 'Survey_responses.xlsx';
scriptDir  = fileparts(mfilename('fullpath'));
if isempty(scriptDir); scriptDir = pwd; end
filePath   = fullfile(scriptDir,'data',dataFile);
resultsDir = fullfile(scriptDir,'results');
sheet      = 'Form Responses 1';

alpha    = 0.05;
nPerm    = 10000;     % number of permutations (Monte Carlo SE of a p-value near 0.05 is about 0.002)
rngSeed  = 42;

% Values that cannot be recomputed from the cleaned spreadsheet (set manually):
nConsortiumCenters   = 55;   % centers in the sEEG Consortium
rawResponsesReceived = 45;   % responses received before removal of duplicate submissions

cleanPctESMLabel = true;     % include centers with "0% (can skip this section)" as 0%

if ~exist(resultsDir,'dir'); mkdir(resultsDir); end
reportFile = fullfile(resultsDir,'manuscript_numbers_report.txt');
if exist(reportFile,'file'); delete(reportFile); end
diary(reportFile); diary on;

global NUMLOG
NUMLOG = {};
setSeed(rngSeed);

%% ============================================================
% 1. LOAD
% =============================================================
raw  = readcell(filePath,'Sheet',sheet);
data = raw(2:end,:);
N    = size(data,1);

fprintf('======================================================\n');
fprintf('MANUSCRIPT NUMBERS  |  file: %s\n',filePath);
fprintf('N survey responses (rows) = %d\n',N);
fprintf('======================================================\n');

% --- Cleaning of labels that carry skip instructions / typos ---
col17 = colStr(data(:,17));
if cleanPctESMLabel
    col17 = strrep(col17,' (can skip this section)','');
end
col69 = strrep(colStr(data(:,69)),' (will skip this section)','');
col72 = colStr(data(:,72));
typo72 = strcmp(col72,'30% of all iEEG cases');       % exact match only
if any(typo72)
    fprintf('NOTE: %d SPES off-ASM answer(s) read "30%% of all iEEG cases"; treated as ">30%% of all iEEG cases" (apparent typo in the option label).\n',sum(typo72));
    col72(typo72) = {'>30% of all iEEG cases'};
end

% One free-text "Other" answer contains commas and would be split into several
% options by the comma-based multi-select parser; its commas are removed so it
% is counted as one reason (text must match the spreadsheet exactly).
col24 = colStr(data(:,24));
ftOld = 'Of note, Would do low-frequency stimulation off ASM if needed, not HF';
ftNew = 'Of note Would do low-frequency stimulation off ASM if needed not HF';
hit24 = ~cellfun(@isempty,strfind(col24,ftOld));
if any(hit24)
    fprintf('NOTE: %d ESM off-ASM reason answer(s) contain a free-text item with commas; commas removed so it counts as one reason.\n',sum(hit24));
    col24(hit24) = strrep(col24(hit24),ftOld,ftNew);
end

%% ============================================================
% 2. GROUPING VARIABLES
% =============================================================
region   = colStr(data(:,4));
instType = colStr(data(:,7));
ageGrp   = repmat({''},N,1);
setting  = repmat({''},N,1);
for i = 1:N
    a = ~isempty(strfind(instType{i},'Adult'));
    p = ~isempty(strfind(instType{i},'Ped'));
    if a && p;  ageGrp{i} = 'Both';
    elseif a;   ageGrp{i} = 'Adult';
    elseif p;   ageGrp{i} = 'Pediatric';
    end
    if ~isempty(strfind(instType{i},'Academic')); setting{i} = 'Academic'; end
    if ~isempty(strfind(instType{i},'Private'));  setting{i} = 'Private';  end
end

%% ============================================================
% 3. RESULTS 3.1 — GENERAL CATEGORIZATION
% =============================================================
fprintf('\n\n############ RESULTS 3.1  General categorization ############\n');

% --- response accounting ---
centerName = colStr(data(:,3));
[uName,~,iName] = unique(centerName);
nName = accumarray(iName,1);
fprintf('\n[3.1] Responses (rows in cleaned file): %d\n',N);
fprintf('[3.1] Distinct Center_Name values: %d\n',numel(uName));
fprintf('[3.1] Center_Name values with >1 response: %d (adult/pediatric responses from one institution are kept as separate observations)\n',sum(nName>1));
for k = find(nName>1)'
    rows = find(iName==k);
    fprintf('         "%s": %d responses (%s)\n',uName{k},nName(k),strjoin(instType(rows)',' | '));
end
if ~isnan(rawResponsesReceived)
    fprintf('[3.1] Raw responses received (manual config): %d; removed as duplicates: %d; analyzed: %d\n',rawResponsesReceived,rawResponsesReceived-N,N);
end
fprintf('[3.1] Response rate vs consortium (%d centers):\n',nConsortiumCenters);
fprintf('         responses / consortium = %d/%d = %.1f%%\n',N,nConsortiumCenters,100*N/nConsortiumCenters);
fprintf('         distinct institutions / consortium = %d/%d = %.1f%%\n',numel(uName),nConsortiumCenters,100*numel(uName)/nConsortiumCenters);
try
    ts = zeros(N,1);
    for i = 1:N; ts(i) = datenum(data{i,1}); end
    fprintf('[2.2] Response timestamps: first %s, last %s\n',datestr(min(ts),'yyyy-mm-dd'),datestr(max(ts),'yyyy-mm-dd'));
    [~,ord] = sort(ts,'descend');
    fprintf('         latest 3 timestamps: %s\n',strjoin(arrayfun(@(q) datestr(ts(q),'yyyy-mm-dd'),ord(1:min(3,N)),'UniformOutput',false)',', '));
    [~,ord] = sort(ts,'ascend');
    fprintf('         earliest 3 timestamps: %s\n',strjoin(arrayfun(@(q) datestr(ts(q),'yyyy-mm-dd'),ord(1:min(3,N)),'UniformOutput',false)',', '));
catch
    fprintf('[2.2] (timestamps not readable as dates - skipped)\n');
end

% --- region / setting / age group ---
printTab('3.1','Region',region,{'South','West','Northeast','Midwest','Canada'},true);
printTab('3.1','Setting (Academic/Private)',setting,{'Academic','Private'},false);
printTab('3.1','Age group treated',ageGrp,{'Adult','Pediatric','Both'},false);
printTab('3.1','Institution-type (raw)',instType,{'Adult-Academic','Ped-Academic','Adult&Ped-Academic','Adult-Private','Ped-Private'},false);

% --- Table 1 ---
fprintf('\n\n############ TABLE 1  ############\n');
printTab('Table1','iEEG per year',colStr(data(:,8)),{'1-10','11-20','21-30','31-40','≥40'},true);
printTab('Table1','Percentage of sEEG among all iEEG',colStr(data(:,9)),{'0-20%','21-40%','41-60%','61-80%','81-100%'},true);
printTab('Table1','Length of stay',colStr(data(:,10)),{'4-6 days','7-10 days','11-14 days','15-21 days'},true);
printTab('Table1','Proportion of iEEG cases undergoing ESM',col17,{'0%','21-40%','41-60%','61-80%','81-100%'},false);
printTab('Table1','Proportion of iEEG cases undergoing SPES/CCEP',col69,{'0%','1-20%','21-40%','41-60%','61-80%','81-100%'},false);

%% ============================================================
% 4. RESULTS 3.2 — GENERAL ESM AND SPES/CCEP PRACTICES
% =============================================================
fprintf('\n\n############ RESULTS 3.2  General ESM and SPES/CCEP practices ############\n');
pctOrd = {'0-20%','21-40%','41-60%','61-80%','81-100%'};

printTab('3.2','ESM used for functional (eloquent) mapping',colStr(data(:,18)),pctOrd,false);
printTab('3.2','ESM used to stimulate seizures',colStr(data(:,19)),pctOrd,false);

% SPES users
spesUser = ~strcmp(col69,'') & ~strcmp(col69,'0%');
nSPES = sum(spesUser);
fprintf('\n[3.2] Centers using SPES/CCEP (PctSPES > 0%%): %d/%d (%.1f%% of all responses)\n',nSPES,N,100*nSPES/N);
fprintf('      cross-check: non-blank SPES indication answers = %d (should equal %d)  %s\n', ...
    sum(~strcmp(colStr(data(:,70)),'')),nSPES,passFail(sum(~strcmp(colStr(data(:,70)),''))==nSPES));
fprintf('[3.2] Centers NOT using SPES/CCEP: %d/%d (%.1f%%)\n',N-nSPES,N,100*(N-nSPES)/N);

printMulti('3.2','SPES/CCEP indications (denominator = SPES/CCEP users)',colStr(data(:,70)), ...
    {'To localize seizure onset zone','To localize functional networks','For research','To induce seizures','To produce after-discharges'});

fprintf('\n--- Seizure induction frequencies ---\n');
printTab('3.2','Seizure induction during epileptic NETWORK mapping',colStr(data(:,25)),pctOrd,false);
printTab('3.2','Seizure induction during FUNCTIONAL mapping',colStr(data(:,26)),pctOrd,false);
printTab('3.2','Seizure induction during SPES/CCEP',colStr(data(:,74)),pctOrd,false);

fprintf('\n--- Timing of ESM ---\n');
printMulti('3.2','ESM timing (denominator = answering centers)',colStr(data(:,21)), ...
    {'On the last 1-2 days before explantation','On the next day after implantation', ...
     'After recording spontaneous habitual clinical seizures', ...
     'Any day in between the day after implantation and few days before the explantation','On the day of implantation'});
printTab('3.2','Number of ESM sessions',colStr(data(:,22)),{'Single session','Two sessions','Three or more sessions'},false);
printMulti('3.2','SPES/CCEP timing (denominator = SPES/CCEP users)',colStr(data(:,71)), ...
    {'On the last 1-2 days before the explantation','On the next day after implantation', ...
     'After recording spontaneous habitual clinical seizures', ...
     'Any day in between the day after implantation and few days before the explantation'});

fprintf('\n--- ESM on/off ASM ---\n');
printTab('3.2','ESM performed off ASM',colStr(data(:,23)), ...
    {'Never (may skip the next question)','Yes, in <5% of all iEEG cases','Yes, in 5-30% of all iEEG cases','Yes, in >30% of all iEEG cases'},false);
printMulti('3.2','Reasons for ESM off ASM (denominator = answering centers)',col24, ...
    {'To induce seizures','To localize seizure onset zone'});

fprintf('\n--- SPES/CCEP on/off ASM ---\n');
printTab('3.2','SPES/CCEP performed off ASM (denominator = SPES/CCEP users)',col72, ...
    {'Never','1-5% of all iEEG cases','5-30% of all iEEG cases','>30% of all iEEG cases'},false);
printMulti('3.2','Reasons for SPES/CCEP off ASM (denominator = answering centers)',colStr(data(:,73)), ...
    {'No time prior to starting ASM','To localize seizure onset zone','To induce seizures','To produce after-discharges'});

%% ============================================================
% 5. RESULTS 3.3 — STIMULATION PARAMETERS (Figure 4 / Figure S1)
% =============================================================
fprintf('\n\n############ RESULTS 3.3  Stimulation parameters ############\n');
pulseLabels = {'<0.05 ms','0.05 ms','0.1 ms','0.2 ms','0.3 ms','0.4 ms','0.5 ms','1 ms','2 ms','>2 ms'};
gridDefs = { 27:36,'sEEG - ESM functional'; 37:46,'sEEG - ESM network'; ...
             47:56,'Subdural - ESM functional'; 57:66,'Subdural - ESM network'; ...
             75:84,'sEEG - SPES/CCEP'; 85:94,'Subdural - SPES/CCEP'};
for k = 1:size(gridDefs,1)
    printGrid(data,gridDefs{k,1},gridDefs{k,2},pulseLabels,true);
end

fprintf('\n--- Same grids split by age group (Figure S1): center-level marginals ---\n');
for a = {'Adult','Pediatric','Both'}
    rows = strcmp(ageGrp,a{1});
    fprintf('\n===== %s centers (n=%d) =====\n',a{1},sum(rows));
    for k = 1:size(gridDefs,1)
        printGrid(data(rows,:),gridDefs{k,1},[gridDefs{k,2} ' | ' a{1}],pulseLabels,false);
    end
end

fprintf('\n--- Stimulation duration per trial ---\n');
printTab('3.3','Low-frequency stimulation duration',colStr(data(:,67)),{'0.5-1 sec','1-5 sec','5-10 sec','10-20 sec','>20 sec'},false);
printTab('3.3','High-frequency stimulation duration',colStr(data(:,68)),{'0.5-1 sec','1-5 sec','5-10 sec','10-20 sec','>20 sec'},false);

fprintf('\n--- SPES/CCEP pulses per train and current (descriptive; not quoted in the text) ---\n');
printTab('3.3','Number of single pulses per train',colStr(data(:,95)),{'<10','11-20','21-30','31-50','>100'},false);
printTab('3.3','Most common SPES/CCEP current',colStr(data(:,96)),{'2 mA','3 mA','5 mA','6 mA'},false);

%% ============================================================
% 6. RESULTS 3.3 (second) — ASSOCIATIONS WITH CENTER FEATURES
% =============================================================
fprintf('\n\n############ RESULTS  Association of center features with practices ############\n');
fprintf('Permutation tests: nPerm=%d, seed=%d. Monte Carlo SE of a p-value near 0.05 = %.4f, near 0.50 = %.4f\n', ...
    nPerm,rngSeed,sqrt(0.05*0.95/nPerm),sqrt(0.5*0.5/nPerm));

% name, data column, ordered categories, ESM-practice outcome flag (1 = included in the ESM-only FDR family)
V = { ...
 'iEEGperYear',        8, {'1-10','11-20','21-30','31-40','≥40'}, 0; ...
 'PctSEEG',            9, {'0-20%','21-40%','41-60%','61-80%','81-100%'}, 0; ...
 'LOS',               10, {'4-6 days','7-10 days','11-14 days','15-21 days'}, 0; ...
 'PctESM',            17, {'0%','21-40%','41-60%','61-80%','81-100%'}, 1; ...
 'ESM_EloquentFreq',  18, pctOrd, 1; ...
 'ESM_SeizureFreq',   19, pctOrd, 1; ...
 'ESM_Sessions',      22, {'Single session','Two sessions','Three or more sessions'}, 1; ...
 'ESM_OffASM',        23, {'Never (may skip the next question)','Yes, in <5% of all iEEG cases','Yes, in 5-30% of all iEEG cases','Yes, in >30% of all iEEG cases'}, 1; ...
 'SeizInd_NetworkMap',25, pctOrd, 1; ...
 'SeizInd_FuncMap',   26, pctOrd, 1; ...
 'StimDur_LowFreq',   67, {'0.5-1 sec','1-5 sec','5-10 sec','10-20 sec','>20 sec'}, 1; ...
 'StimDur_HighFreq',  68, {'0.5-1 sec','1-5 sec','5-10 sec'}, 1};
nV = size(V,1);

ordVals = nan(N,nV);
for j = 1:nV
    if V{j,2} == 17
        x = col17;
    else
        x = colStr(data(:,V{j,2}));
    end
    [tf,loc] = ismember(x,V{j,3});
    ordVals(tf,j) = loc(tf);
    unl = x(~tf & ~strcmp(x,''));
    if ~isempty(unl)
        fprintf('WARNING: %s has %d answer(s) not in its category list and excluded (e.g. "%s")\n',V{j,1},numel(unl),unl{1});
    end
end

esmFlag = cell2mat(V(:,4)) == 1;
famNames = {'Region','AgeGroup'};
famGroups = {region, ageGrp};
KW = struct();
for f = 1:2
    g = famGroups{f};
    H = nan(nV,1); df = nan(nV,1); p = nan(nV,1); n = nan(nV,1);
    for j = 1:nV
        y = ordVals(:,j);
        ok = ~isnan(y) & ~strcmp(g,'');
        [H(j),df(j),p(j)] = permKW(y(ok),g(ok),nPerm);
        n(j) = sum(ok);
    end
    pF = bhFDR(p);
    pFesm = nan(nV,1); pFesm(esmFlag) = bhFDR(p(esmFlag));
    KW.(famNames{f}) = struct('H',H,'df',df,'p',p,'pFDR',pF,'pFDResm',pFesm,'N',n);

    fprintf('\n[3.3b] Permutation Kruskal-Wallis by %s  (FDR family = all %d outcomes)\n',famNames{f},nV);
    fprintf('   %-20s %8s %3s %8s %9s %14s %4s\n','Outcome','H','df','p','p_FDR(12)','FDR ESM9 (sens)','N');
    for j = 1:nV
        fprintf('   %-20s %8.2f %3d %8.3f %9.3f %14s %4d\n',V{j,1},H(j),df(j),p(j),pF(j),fmtNaN(pFesm(j)),n(j));
    end
    fid = fopen(fullfile(resultsDir,sprintf('stats_%s_KW.csv',lower(famNames{f}))),'w');
    fprintf(fid,'Outcome,Grouping,H,df,p,p_FDR_all12,p_FDR_ESMonly9,N\n');
    for j = 1:nV
        fprintf(fid,'%s,%s,%.4f,%d,%.4f,%.4f,%s,%d\n',V{j,1},famNames{f},H(j),df(j),p(j),pF(j),fmtNaN(pFesm(j)),n(j));
    end
    fclose(fid);
    printSig(famNames{f},V(:,1),p,pF,alpha);
end

% --- Spearman: annual iEEG volume vs ESM outcomes ---
fprintf('\n[3.3b] Permutation Spearman: annual iEEG volume vs ESM outcomes (two-sided; FDR family = %d outcomes)\n',sum(esmFlag & ~strcmp(V(:,1),'iEEGperYear')));
vol = ordVals(:,1);
spIdx = find(esmFlag);
rho = nan(numel(spIdx),1); pS = rho; nS = rho;
for q = 1:numel(spIdx)
    y = ordVals(:,spIdx(q));
    ok = ~isnan(vol) & ~isnan(y);
    [rho(q),pS(q)] = permSpearman(vol(ok),y(ok),nPerm);
    nS(q) = sum(ok);
end
pSF = bhFDR(pS);
fprintf('   %-20s %8s %8s %9s %4s\n','Outcome','rho','p','p_FDR','N');
for q = 1:numel(spIdx)
    fprintf('   %-20s %8.3f %8.3f %9.3f %4d\n',V{spIdx(q),1},rho(q),pS(q),pSF(q),nS(q));
end
fid = fopen(fullfile(resultsDir,'stats_ieegvolume_spearman.csv'),'w');
fprintf(fid,'Outcome,rho,p,p_FDR,N\n');
for q = 1:numel(spIdx)
    fprintf(fid,'%s,%.4f,%.4f,%.4f,%d\n',V{spIdx(q),1},rho(q),pS(q),pSF(q),nS(q));
end
fclose(fid);
printSig('iEEG volume (Spearman)',V(spIdx,1),pS,pSF,alpha);

% --- manuscript-style sentences ---
fprintf('\n[3.3b] Manuscript-style strings (H, df, p raw, FDR-adjusted p)\n');
for f = 1:2
    for j = 1:nV
        fprintf('   %-9s %-20s H=%.2f, df=%d, p=%.3f, FDR-adjusted p=%.3f\n',famNames{f},V{j,1}, ...
            KW.(famNames{f}).H(j),KW.(famNames{f}).df(j),KW.(famNames{f}).p(j),KW.(famNames{f}).pFDR(j));
    end
end
for q = 1:numel(spIdx)
    fprintf('   Spearman  %-20s rho=%.3f, p=%.3f, FDR-adjusted p=%.3f\n',V{spIdx(q),1},rho(q),pS(q),pSF(q));
end

%% ============================================================
% 7. HEADLINE NUMBERS (Abstract / Discussion)
% =============================================================
fprintf('\n\n############ HEADLINE NUMBERS ############\n');
n8100 = sum(strcmp(col17,'81-100%'));
nNoESM = sum(strncmp(col17,'0%',2));
fprintf('Centers using ESM in 81-100%% of iEEG cases: %d/%d (%.1f%%)\n',n8100,N,100*n8100/N);
fprintf('Centers reporting no ESM (0%%): %d/%d (%.1f%%)\n',nNoESM,N,100*nNoESM/N);
fprintf('Centers using SPES/CCEP: %d/%d (%.1f%%)\n',nSPES,N,100*nSPES/N);
fprintf('Academic centers: %d/%d (%.1f%%); private: %d/%d (%.1f%%)\n',sum(strcmp(setting,'Academic')),N,100*sum(strcmp(setting,'Academic'))/N,sum(strcmp(setting,'Private')),N,100*sum(strcmp(setting,'Private'))/N);
nFDR = 0; nNom = 0;
for f = 1:2
    nFDR = nFDR + sum(KW.(famNames{f}).pFDR < alpha);
    nNom = nNom + sum(KW.(famNames{f}).p < alpha);
end
nFDR = nFDR + sum(pSF < alpha); nNom = nNom + sum(pS < alpha);
fprintf('Inferential tests with nominal p<%.2f: %d ; with FDR-adjusted p<%.2f: %d\n',alpha,nNom,alpha,nFDR);

%% ============================================================
% 8. SAVE LONG-FORMAT NUMBERS
% =============================================================
fid = fopen(fullfile(resultsDir,'numbers_long.csv'),'w');
fprintf(fid,'section,variable,category,n,denominator,percent\n');
for r = 1:size(NUMLOG,1)
    fprintf(fid,'"%s","%s","%s",%d,%d,%.1f\n',NUMLOG{r,1},NUMLOG{r,2},strrep(NUMLOG{r,3},'"','""'),NUMLOG{r,4},NUMLOG{r,5},NUMLOG{r,6});
end
fclose(fid);
fprintf('\nDone. Files written to:\n%s\n',resultsDir);
diary off;

%% ============================================================
% LOCAL FUNCTIONS
% =============================================================
function setSeed(s)
if exist('OCTAVE_VERSION','builtin') ~= 0
    rand('twister',s); %#ok<RAND>
else
    rng(s,'twister');
end
end

function tf = isMissingCell(v)
tf = isempty(v) || (isnumeric(v) && all(isnan(v(:)))) || ...
     (ischar(v) && all(isspace(v))) || isa(v,'missing') || ...
     (isstring(v) && (isscalar(v) && (ismissing(v) || strlength(v)==0)));
end

function s = colStr(c)
s = cell(numel(c),1);
for i = 1:numel(c)
    v = c{i};
    if isMissingCell(v);  s{i} = '';
    elseif ischar(v);     s{i} = strtrim(v);
    elseif isstring(v);   s{i} = strtrim(char(v));
    elseif isnumeric(v);  s{i} = strtrim(num2str(v));
    else;                 s{i} = '';
    end
end
end

function t = passFail(tf)
if tf; t = 'PASS'; else; t = '**FAIL**'; end
end

function s = fmtNaN(x)
if isnan(x); s = 'NA'; else; s = sprintf('%.3f',x); end
end

function logRow(sec,label,cat,n,d)
global NUMLOG
NUMLOG(end+1,:) = {sec,label,cat,n,d,100*n/max(d,1)};
end

function printTab(sec,label,x,order,showSorted)
valid = ~strcmp(x,'');
d = sum(valid);
fprintf('\n[%s] %s  (denominator n=%d of N=%d)\n',sec,label,d,numel(x));
counts = zeros(1,numel(order));
for k = 1:numel(order)
    counts(k) = sum(strcmp(x,order{k}));
    fprintf('   %-46s %3d/%d (%5.1f%%)\n',order{k},counts(k),d,100*counts(k)/max(d,1));
    logRow(sec,label,order{k},counts(k),d);
end
other = x(valid & ~ismember(x,order));
if ~isempty(other)
    [u,~,ic] = unique(other);
    cnt = accumarray(ic,1);
    for k = 1:numel(u)
        fprintf('   %-46s %3d/%d (%5.1f%%)   <-- NOT in category list\n',u{k},cnt(k),d,100*cnt(k)/d);
        logRow(sec,label,['UNLISTED: ' u{k}],cnt(k),d);
    end
end
parts = cell(1,numel(order));
for k = 1:numel(order)
    parts{k} = sprintf('%s: %d/%d (%.1f%%)',order{k},counts(k),d,100*counts(k)/max(d,1));
end
fprintf('   > in listed order: %s\n',strjoin(parts,'; '));
if showSorted
    [~,o] = sort(counts,'descend');
    fprintf('   > by frequency  : %s\n',strjoin(parts(o),'; '));
end
end

function printMulti(sec,label,x,known)
valid = ~strcmp(x,'');
d = sum(valid);
fprintf('\n[%s] %s  (denominator n=%d of N=%d)\n',sec,label,d,numel(x));
tokens = {};
for i = 1:numel(x)
    if ~valid(i); continue; end
    t = strtrim(strsplit(x{i},','));
    t = t(~cellfun(@isempty,t));
    t = unique(t);
    tokens = [tokens, t]; %#ok<AGROW>
end
parts = {};
for k = 1:numel(known)
    n = sum(strcmp(tokens,known{k}));
    fprintf('   %-72s %3d/%d (%5.1f%%)\n',known{k},n,d,100*n/max(d,1));
    logRow(sec,label,known{k},n,d);
    parts{end+1} = sprintf('%s: %d/%d (%.1f%%)',known{k},n,d,100*n/max(d,1)); %#ok<AGROW>
end
other = tokens(~ismember(tokens,known));
if ~isempty(other)
    [u,~,ic] = unique(other);
    cnt = accumarray(ic(:),1);
    [cnt,o] = sort(cnt,'descend'); u = u(o);
    for k = 1:numel(u)
        fprintf('   %-72s %3d/%d (%5.1f%%)   <-- other / free text\n',u{k},cnt(k),d,100*cnt(k)/d);
        logRow(sec,label,['OTHER: ' u{k}],cnt(k),d);
    end
end
fprintf('   > %s\n',strjoin(parts,'; '));
end

function printGrid(data,cols,name,pulseLabels,showMatrix)
nP = numel(cols); n = size(data,1);
tok = cell(nP,n); allTok = {};
for i = 1:nP
    for j = 1:n
        v = data{j,cols(i)};
        if isMissingCell(v); continue; end
        t = strtrim(strsplit(char(v),', '));
        t = t(~cellfun(@isempty,t));
        tok{i,j} = t; allTok = [allTok,t]; %#ok<AGROW>
    end
end
anyCenter = false(n,1);
for j = 1:n
    for i = 1:nP; if ~isempty(tok{i,j}); anyCenter(j) = true; end; end
end
fprintf('\n[3.3] %s  | centers with any selection: %d (of %d in this subset)\n',name,sum(anyCenter),n);
if isempty(allTok); fprintf('   (no data)\n'); return; end
fl = unique(allTok);
key = zeros(1,numel(fl));
for f = 1:numel(fl)
    m = regexp(fl{f},'[\d.]+','match','once');
    if isempty(m); key(f) = Inf; else; key(f) = str2double(m); end
    if fl{f}(1) == '<'; key(f) = key(f) - 0.5; end
    if fl{f}(1) == '>'; key(f) = key(f) + 0.5; end
end
[~,o] = sort(key); fl = fl(o);
M = zeros(nP,numel(fl));
cF = zeros(1,numel(fl)); cP = zeros(nP,1);
for j = 1:n
    usedF = false(1,numel(fl));
    for i = 1:nP
        t = tok{i,j};
        if isempty(t); continue; end
        cP(i) = cP(i) + 1;
        for q = 1:numel(t)
            f = find(strcmp(fl,t{q}),1);
            M(i,f) = M(i,f) + 1; usedF(f) = true;
        end
    end
    cF = cF + usedF;
end
d = sum(anyCenter);
fprintf('   Centers choosing each frequency (any pulse width): ');
for f = 1:numel(fl); fprintf('%s: %d/%d (%.1f%%)  ',fl{f},cF(f),d,100*cF(f)/max(d,1)); logRow('3.3',[name ' | freq'],fl{f},cF(f),d); end
fprintf('\n   Centers choosing each pulse width (any frequency): ');
for i = 1:nP; if cP(i) > 0; fprintf('%s: %d/%d (%.1f%%)  ',pulseLabels{i},cP(i),d,100*cP(i)/max(d,1)); end; logRow('3.3',[name ' | pulse width'],pulseLabels{i},cP(i),d); end
fprintf('\n');
if showMatrix
    fprintf('   Cell counts (pulse width x frequency; a center can select several cells):\n');
    fprintf('   %-10s',''); fprintf('%10s',fl{:}); fprintf('\n');
    for i = 1:nP
        fprintf('   %-10s',pulseLabels{i}); fprintf('%10d',M(i,:)); fprintf('\n');
    end
    [mx,ix] = max(M(:)); [ri,ci] = ind2sub(size(M),ix);
    fprintf('   Most selected cell: %s @ %s (%d selections)\n',pulseLabels{ri},fl{ci},mx);
end
end

function r = avgRank(y)
y = y(:); n = numel(y);
[ys,ord] = sort(y);
r = zeros(n,1);
i = 1;
while i <= n
    j = i;
    while j < n && ys(j+1) == ys(i); j = j + 1; end
    r(ord(i:j)) = (i + j)/2;
    i = j + 1;
end
end

function [H,df,p] = permKW(y,g,nPerm)
y = y(:);
[lv,~,gi] = unique(g(:));
k = numel(lv); n = numel(y); df = k - 1;
if k < 2 || n < 2; H = 0; p = 1; return; end
r = avgRank(y);
[~,~,ic] = unique(y);
t = accumarray(ic,1);
tc = 1 - sum(t.^3 - t)/(n^3 - n);
ns = accumarray(gi,1);
H = kwFromLabels(r,gi,ns,n,k,tc);
cnt = 0;
for it = 1:nPerm
    pg = gi(randperm(n));
    Hp = kwFromLabels(r,pg,ns,n,k,tc);
    if Hp >= H - 1e-9; cnt = cnt + 1; end
end
p = (cnt + 1)/(nPerm + 1);
end

function H = kwFromLabels(r,gi,ns,n,k,tc)
s = accumarray(gi,r,[k 1]);
H = 12/(n*(n+1)) * sum(ns .* (s./ns - (n+1)/2).^2);
if tc > 0; H = H/tc; end
end

function [rho,p] = permSpearman(x,y,nPerm)
x = x(:); y = y(:); n = numel(x);
rx = avgRank(x); ry = avgRank(y);
rxc = (rx - mean(rx))/sqrt(sum((rx - mean(rx)).^2));
ryc = (ry - mean(ry))/sqrt(sum((ry - mean(ry)).^2));
rho = sum(rxc .* ryc);
cnt = 0;
for it = 1:nPerm
    rp = sum(rxc .* ryc(randperm(n)));
    if abs(rp) >= abs(rho) - 1e-12; cnt = cnt + 1; end
end
p = (cnt + 1)/(nPerm + 1);
end

function q = bhFDR(p)
p = p(:); q = nan(size(p));
v = ~isnan(p); pv = p(v);
if isempty(pv); return; end
[ps,idx] = sort(pv); m = numel(ps);
qs = ps .* m ./ (1:m)';
qs = flipud(cummin(flipud(qs)));
qs = min(qs,1);
tmp = nan(size(pv)); tmp(idx) = qs;
q(v) = tmp;
end

function printSig(famName,names,p,pF,alpha)
fprintf('   -> %s: nominal p<%.2f: ',famName,alpha);
s = find(p < alpha);
if isempty(s); fprintf('none'); else; for q = s(:)'; fprintf('%s (p=%.3f, FDR p=%.3f)  ',names{q},p(q),pF(q)); end; end
fprintf('\n   -> %s: FDR-adjusted p<%.2f: ',famName,alpha);
s = find(pF < alpha);
if isempty(s); fprintf('none'); else; for q = s(:)'; fprintf('%s (FDR p=%.3f)  ',names{q},pF(q)); end; end
fprintf('\n');
end
